import{_ as d,o as a,a as e,b as r}from"./app.DII24pJb.js";const B=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬入总体说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_compute_load_overall_description"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_compute_load_overall_description.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_compute_load_overall_description.md","outlineHeaders":[{"level":2,"title":"GM->L1 Buffer的接口分类与使用场景","slug":"GM->L1-Buffer的接口分类与使用场景","link":"#GM->L1-Buffer的接口分类与使用场景"},{"level":2,"title":"UB->L1 Buffer的接口分类与使用场景","slug":"UB->L1-Buffer的接口分类与使用场景","link":"#UB->L1-Buffer的接口分类与使用场景"},{"level":2,"title":"L1 Buffer->L0A Buffer/L0B Buffer的接口分类与使用场景","slug":"L1-Buffer->L0A-Buffer/L0B-Buffer的接口分类与使用场景","link":"#L1-Buffer->L0A-Buffer/L0B-Buffer的接口分类与使用场景"},{"level":2,"title":"辅助配置接口说明","slug":"辅助配置接口说明","link":"#辅助配置接口说明"}],"lastUpdated":1789956443000}'),_={name:"api/SIMD-API/c_api/cube_datamove/cube_compute_load_overall_description.md"};function f(l,t,c,o,s,h){return a(),e("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>矩阵搬入总体说明</h1><p>矩阵计算的搬入是Ascend C编程框架中用于数据搬运的一类核心接口，主要实现Global Memory到L0A Buffer/L0B Buffer之间的数据高效传输。该类接口提供了多种数据搬运模式，能够满足矩阵计算中左右矩阵等数据的搬运需求，通常与Mmad接口配合使用。</p><p>矩阵计算的搬入的接口支持多种数据搬运场景，包括但不限于<strong>二维格式数据搬运、三维格式转换、压缩数据解压、矩阵转置搬运以及稀疏化数据处理</strong>等。通过灵活配置不同的参数结构体，开发者可以精确控制数据的搬运路径、起始位置、搬运长度等关键信息，充分利用硬件的数据搬运能力，最大化算子的整体执行性能。</p><p>矩阵计算的搬入接口支持多种数据通路，每种通路对应特定的存储层级和访问特性。</p><p><strong>表1</strong> <strong>数据通路和存储层级</strong></p><table><thead><tr><th>源位置</th><th>源地址对齐要求</th><th>目的位置</th><th>目的地址对齐要求</th><th>典型应用场景</th></tr></thead><tbody><tr><td>Global Memory</td><td>1字节</td><td>L1 Buffer（<code>__cbuf__</code>，A矩阵）</td><td>32字节</td><td>从全局内存加载左矩阵数据到L1 Buffer。</td></tr><tr><td>Global Memory</td><td>1字节</td><td>L1 Buffer（<code>__cbuf__</code>，B矩阵）</td><td>32字节</td><td>从全局内存加载右矩阵数据到L1 Buffer。</td></tr><tr><td>Global Memory</td><td>1字节</td><td>L0A Buffer（<code>__ca__</code>）</td><td>512字节</td><td>从全局内存加载左矩阵数据到L0A Buffer。</td></tr><tr><td>Global Memory</td><td>1字节</td><td>L0B Buffer（<code>__cb__</code>）</td><td>512字节</td><td>从全局内存加载右矩阵数据到L0B Buffer。</td></tr><tr><td>L1 Buffer（<code>__cbuf__</code>，A矩阵）</td><td>32字节</td><td>L0A Buffer（<code>__ca__</code>）</td><td>512字节</td><td>从L1 Buffer加载左矩阵数据到L0A Buffer。</td></tr><tr><td>L1 Buffer（<code>__cbuf__</code>，B矩阵）</td><td>32字节</td><td>L0B Buffer（<code>__cb__</code>）</td><td>512字节</td><td>从L1 Buffer加载右矩阵数据到L0B Buffer。</td></tr><tr><td>L1 Buffer</td><td>32字节</td><td>BiasTable Buffer</td><td>64字节</td><td>从L1 Buffer加载存储矩阵计算所需的Bias（偏置）数据到BiasTable Buffer。</td></tr><tr><td>L1 Buffer</td><td>32字节</td><td>Fixpipe Buffer</td><td>128字节</td><td>从L1 Buffer加载Fixpipe搬运过程中所需的量化参数等数据到Fixpipe Buffer。</td></tr></tbody></table><div data-filter="950"><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>Ascend 950PR&amp;950DT系列产品因硬件变更，删除GM到L0A Buffer、L0B Buffer的数据通路。产生的影响是原GM到L0A Buffer和L0B Buffer的数据搬运需要拆分为两步，即从GM到L1 Buffer的数据搬运和从L1 Buffer到L0A Buffer、L0B Buffer的数据搬运。</p></div></div><h2 id="GM-&gt;L1-Buffer的接口分类与使用场景">GM-&gt;L1 Buffer的接口分类与使用场景<a class="header-anchor" href="#GM-&gt;L1-Buffer的接口分类与使用场景">​</a></h2><p><strong>表2</strong> GM-&gt;L1 Buffer接口</p><table><thead><tr><th>接口类别</th><th>主要功能</th><th>支持通路</th><th>典型应用场景</th></tr></thead><tbody><tr><td><a href="asc_copy_gm2l1/asc_copy_gm2l1.html">asc_copy_gm2l1</a>，连续/高维切分重载</td><td>拷贝已排布数据，保持内容和格式</td><td>GM-&gt;L1 Buffer</td><td>完整矩阵、非连续矩阵分片</td></tr><tr><td><a href="asc_copy_gm2l1_nd2nz/asc_copy_gm2l1_nd2nz.html">asc_copy_gm2l1_nd2nz</a></td><td>搬运并将ND转为Nz</td><td>GM-&gt;L1 Buffer</td><td>线性矩阵输入</td></tr><tr><td><a href="asc_copy_gm2l1/asc_copy_gm2l1.html">asc_copy_gm2l1</a>，2D分形重载</td><td>按分形搬运</td><td>GM-&gt;L1 Buffer</td><td>离线分形数据</td></tr></tbody></table><div data-filter="950"><p>针对Ascend 950PR&amp;950DT系列产品，新增GM-&gt;L1 Buffer如下接口，请开发者参考表3。</p><p><strong>表3</strong> GM-&gt;L1 Buffer接口</p><table><thead><tr><th>接口类别</th><th>主要功能</th><th>支持通路</th><th>典型应用场景</th></tr></thead><tbody><tr><td><a href="asc_copy_gm2l1_dn2nz.html">asc_copy_gm2l1_dn2nz</a></td><td>DN-&gt;Nz</td><td>GM-&gt;L1 Buffer</td><td>列主序矩阵输入</td></tr><tr><td><a href="asc_copy_gm2l1_align.html">asc_copy_gm2l1_align</a></td><td>非对齐搬运及左右Padding</td><td>GM-&gt;L1 Buffer</td><td>字节长度、边界不满足普通块拷贝要求</td></tr><tr><td><a href="asc_copy_gm2l1/asc_copy_gm2l1_2d_arch_3510.html">asc_copy_gm2l1（2D）</a></td><td>2DV2分形搬运，可配L2 Cache策略</td><td>GM-&gt;L1 Buffer</td><td>多方向分形块输入</td></tr><tr><td><a href="asc_copy_gm2l1/asc_copy_gm2l1_highdim_split_arch_3510.html">asc_copy_gm2l1（高维切分）</a></td><td>支持<code>asc_channel_pad_mode</code>通道填充/压缩</td><td>GM-&gt;L1 Buffer</td><td>按32B通道扩展有效区或去除高位字节</td></tr></tbody></table></div><div data-filter="950"><h2 id="UB-&gt;L1-Buffer的接口分类与使用场景">UB-&gt;L1 Buffer的接口分类与使用场景<a class="header-anchor" href="#UB-&gt;L1-Buffer的接口分类与使用场景">​</a></h2><p><strong>表4</strong> UB-&gt;L1 Buffer接口</p><table><thead><tr><th>接口类别</th><th>主要功能</th><th>支持通路</th><th>典型应用场景</th></tr></thead><tbody><tr><td><a href="../vector_datamove/asc_copy_ub2l1.html">asc_copy_ub2l1</a>连续重载</td><td>连续数据搬运</td><td>UB-&gt;L1 Buffer</td><td>矢量结果送入矩阵计算</td></tr><tr><td>同接口高维切分重载</td><td>按32B块配置长度和间隔</td><td>UB-&gt;L1 Buffer</td><td>非连续矢量结果搬运</td></tr></tbody></table></div><h2 id="L1-Buffer-&gt;L0A-Buffer/L0B-Buffer的接口分类与使用场景">L1 Buffer-&gt;L0A Buffer/L0B Buffer的接口分类与使用场景<a class="header-anchor" href="#L1-Buffer-&gt;L0A-Buffer/L0B-Buffer的接口分类与使用场景">​</a></h2><p><strong>表5</strong> L1 Buffer-&gt;L0A/B Buffer接口</p><table><thead><tr><th>接口类别</th><th>主要功能</th><th>支持通路</th><th>典型应用场景</th></tr></thead><tbody><tr><td><a href="asc_copy_l12l0a/asc_copy_l12l0a.html">asc_copy_l12l0a</a>、<a href="asc_copy_l12l0b/asc_copy_l12l0b.html">asc_copy_l12l0b</a>的2D重载</td><td>按512B分形搬运</td><td>L1 Buffer-&gt;L0A Buffer/L0B Buffer</td><td>普通矩阵输入</td></tr><tr><td>同接口的3D重载</td><td>NC1HWC0输入在线img2col</td><td>L1 Buffer-&gt;L0A Buffer/L0B Buffer</td><td>卷积展开</td></tr><tr><td><a href="asc_copy_l12l0a_trans.html">asc_copy_l12l0a_trans</a>、<a href="asc_copy_l12l0b_trans/asc_copy_l12l0b_trans.html">asc_copy_l12l0b_trans</a></td><td>拼接分形后转置搬运</td><td>L1 Buffer-&gt;L0A Buffer/L0B Buffer</td><td>特定位宽的块转置</td></tr><tr><td><a href="asc_copy_l12bt/asc_copy_l12bt.html">asc_copy_l12bt</a></td><td>Bias搬入</td><td>L1 Buffer-&gt;BiasTable</td><td>累加初值</td></tr><tr><td><a href="asc_copy_l12fb/asc_copy_l12fb.html">asc_copy_l12fb</a></td><td>随路系数搬入</td><td>L1 Buffer-&gt;Fixpipe Buffer</td><td>量化/激活</td></tr></tbody></table><div data-filter="910b,A3"><p>针对Atlas A2训练系列产品/Atlas A2推理系列产品和Atlas A3训练系列产品/Atlas A3推理系列产品，支持L1 Buffer-&gt;L0B Buffer如下接口，请开发者参考表6。</p><p><strong>表6</strong> 稀疏矩阵搬运</p><table><thead><tr><th>接口类别</th><th>主要功能</th><th>支持通路</th><th>典型应用场景</th></tr></thead><tbody><tr><td><a href="asc_copy_l12l0b_sparse.html">asc_copy_l12l0b_sparse</a></td><td>搬运4选2结构化稀疏矩阵计算所需的稠密化权重矩阵和索引矩阵。</td><td>L1 Buffer-&gt;L0B Buffer</td><td>稀疏矩阵乘法计算数据搬入。</td></tr></tbody></table></div><div data-filter="950"><p>针对Ascend 950PR&amp;950DT系列产品，新增如下接口，请开发者参考表7。</p><p><strong>表7</strong> 3510二维和MX扩展</p><table><thead><tr><th>接口</th><th>功能</th><th>使用方式</th></tr></thead><tbody><tr><td><code>asc_copy_l12l0a</code> / <code>asc_copy_l12l0b</code>的2D重载</td><td>2D二维分形搬运，支持FP4/FP8/HiFloat8及整数位宽</td><td>设置<code>m_step</code>、<code>k_step</code>和源/目标步长</td></tr><tr><td><code>asc_copy_l12l0a_transpose</code> / <code>asc_copy_l12l0b_transpose</code></td><td>同一2DV2指令的转置变体</td><td>与普通2D重载参数布局对应；不是<code>_trans</code>指令</td></tr><tr><td><a href="asc_copy_l12l0a_mx.html">asc_copy_l12l0a_mx</a> / <a href="asc_copy_l12l0b_mx.html">asc_copy_l12l0b_mx</a></td><td>只搬运32B分形的E8M0系数</td><td>与A/B数据搬运分别调用，匹配映射地址</td></tr></tbody></table></div><h2 id="辅助配置接口说明">辅助配置接口说明<a class="header-anchor" href="#辅助配置接口说明">​</a></h2><p><strong>表8</strong> 辅助配置接口</p><table><thead><tr><th>接口</th><th>功能</th><th>架构/注意事项</th></tr></thead><tbody><tr><td><a href="asc_fill_l1.html">asc_fill_l1</a>、<a href="asc_fill_l0a.html">asc_fill_l0a</a>、<a href="asc_fill_l0b.html">asc_fill_l0b</a></td><td>初始化Buffer</td><td>支持L1 Buffer、L0A Buffer、L0B Buffer</td></tr><tr><td><a href="asc_set_l13d_fmatrix.html">asc_set_l13d_fmatrix</a>、<a href="asc_set_l13d_fmatrix_b.html">asc_set_l13d_fmatrix_b</a></td><td>FeatureMap尺寸和Padding边界</td><td>根据A/B侧与<code>f_matrix_ctrl</code>选择</td></tr><tr><td><a href="asc_set_l12l0a_3d_padding.html">asc_set_l12l0a_3d_padding</a>、<a href="asc_set_l12l0b_3d_padding.html">asc_set_l12l0b_3d_padding</a></td><td>Padding配置</td><td>根据A/B侧与<code>f_matrix_ctrl</code>选择</td></tr><tr><td><a href="asc_set_l13d_size.html">asc_set_l13d_size</a></td><td>L1 Buffer边界大小</td><td>按对应3D接口要求</td></tr><tr><td><a href="asc_set_l13d_rpt.html">asc_set_l13d_rpt</a></td><td>3D重复和步长</td><td>按对应重载配置</td></tr><tr><td><a href="asc_load_image_to_cbuf.html">asc_load_image_to_cbuf</a></td><td>图像搬入L1 Buffer</td><td>按该接口支持范围配置</td></tr><tr><td><a href="asc_copy_l12l0c.html">asc_copy_l12l0c</a></td><td>L1 Buffer-&gt;L0C Buffer初值搬运</td><td>初始化路径的补充</td></tr><tr><td><a href="asc_set_l12l0a_3d_padding.html">asc_set_l12l0a_3d_padding</a>、<a href="asc_set_l12l0b_3d_padding.html">asc_set_l12l0b_3d_padding</a></td><td>带类型的Padding值配置</td><td>注意两侧寄存器及共享配置</td></tr></tbody></table></article></div>',1)])])}const u=d(_,[["render",f]]);export{B as __pageData,u as default};
